const eventDetail=e=>{const p=e.payload?.payload||e.payload||{},parts=[];if(p.plate||p.license_plate)parts.push(p.plate||p.license_plate);if(p.count!==undefined)parts.push(`Count ${p.count}`);if(p.confidence!==undefined)parts.push(`${Math.round(Number(p.confidence)*100)}% confidence`);return parts.join(' · ')||String(p.message||p.description||'Analytics event received')};
function eventNumbers(event){const root=event.payload?.payload||event.payload||{},found=[];function visit(value,prefix='',depth=0){if(depth>2||found.length>=6||!value||typeof value!=='object'||Array.isArray(value))return;for(const [key,nested] of Object.entries(value)){const label=prefix?`${prefix} ${key}`:key;if(typeof nested==='number'&&Number.isFinite(nested)&&/(count|total|occupancy|entries|exits|current|inside|queue|speed|duration)/i.test(key)&&!/(id|timestamp)$/i.test(key))found.push([humanize(label.replaceAll(' ','_')),nested]);else if(typeof nested==='object')visit(nested,label,depth+1)}}visit(root);return found.slice(0,4)}
