function analyticsEventCard(event){const type=eventType(event),p=event.payload?.payload||event.payload||{},alert=type==='alert'||['warning','error','critical'].includes(String(p.severity||event.payload?.severity||'').toLowerCase()),when=new Date(event.occurred_at||event.received_at*1000),numbers=eventNumbers(event),hasSnapshot=Boolean(primaryEventSnapshot(event));return`<article class="analytics-event ${alert?'alert':''} ${hasSnapshot?'has-snapshot':''}" data-analytics-event="${esc(event.event_id)}" ${hasSnapshot?'tabindex="0" role="button" aria-label="Show event snapshot"':''}><span class="analytics-event-icon">${alert?'!':'◎'}</span><div><strong>${esc(type.replaceAll('_',' '))}</strong><small>${esc(eventCamera(event)||'Unknown camera')} · ${esc(eventDetail(event))}${hasSnapshot?' · View snapshot':''}</small>${numbers.length?`<div class="event-numbers">${numbers.map(([label,value])=>`<span><b>${esc(value)}</b>${esc(label)}</span>`).join('')}</div>`:''}</div><time>${esc(Number.isNaN(when.valueOf())?'—':when.toLocaleTimeString())}</time></article>`}
