async function enhanceSolutionAnalytics(drawer,name){if(drawer.dataset.analyticsReady)return;drawer.dataset.analyticsReady='true';const panel=document.createElement('section');panel.className='detail-panel solution-analytics';panel.innerHTML=`<div class="card-top analytics-viewer-head"><div><h3>Latest analytics snapshot</h3><p class="version">Updates when the running solution reports a new event</p></div><div class="actions"><button class="secondary small analytics-latest hidden">Return to latest</button><button class="secondary small analytics-minimize">Minimize</button><span class="analytics-live">Event driven</span></div></div><div class="analytics-featured"><div class="empty">Waiting for an event with a retained snapshot…</div></div><div class="section-head"><h2>Recent events</h2><span class="hint analytics-count">Waiting for events…</span></div><div class="analytics-events"><div class="empty">No analytics events received yet.</div></div>`;drawer.querySelector('.live-editor')?.before(panel);const viewer=panel.querySelector('.analytics-featured'),feed=panel.querySelector('.analytics-events'),latestButton=panel.querySelector('.analytics-latest'),minimizeButton=panel.querySelector('.analytics-minimize'),eventsById=new Map,seenEvents=new Set;let initialHistory=true,selectedEventId=null,latestSnapshotEventId=null;function showEvent(event,reveal=false){if(!event)return;viewer.innerHTML=analyticsFeaturedSnapshot(event);if(reveal){panel.classList.remove('analytics-minimized');minimizeButton.textContent='Minimize'}}function updateFeed(events){for(const event of events)eventsById.set(event.event_id,event);const fresh=events.filter(event=>!seenEvents.has(event.event_id));if(fresh.length){feed.querySelector('.empty')?.remove();const pinnedToTop=feed.scrollTop<8,oldHeight=feed.scrollHeight;for(const event of fresh.slice().reverse()){feed.insertAdjacentHTML('afterbegin',analyticsEventCard(event));seenEvents.add(event.event_id)}if(!pinnedToTop)feed.scrollTop+=feed.scrollHeight-oldHeight}if(!seenEvents.size&&!feed.querySelector('.empty'))feed.innerHTML='<div class="empty">No analytics events received yet.</div>';panel.querySelector('.analytics-count').textContent=`${seenEvents.size} loaded · event stream active`}function updateViewer(events){const latest=events.find(primaryEventSnapshot);if(!latest)return;if(latest.event_id!==latestSnapshotEventId){latestSnapshotEventId=latest.event_id;if(!selectedEventId)showEvent(latest)}}async function refreshEvents(){try{const limit=initialHistory?250:50,result=await api(`/api/telemetry/events?deployment_id=${encodeURIComponent(name)}&limit=${limit}`),events=result.events||[];initialHistory=false;updateFeed(events);updateViewer(events)}catch(error){panel.querySelector('.analytics-count').textContent='Telemetry unavailable'}}function selectEvent(target){const event=eventsById.get(target?.dataset.analyticsEvent);if(!event||!primaryEventSnapshot(event))return;selectedEventId=event.event_id;latestButton.classList.remove('hidden');showEvent(event,true)}feed.addEventListener('click',event=>selectEvent(event.target.closest('.analytics-event')));feed.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();selectEvent(event.target.closest('.analytics-event'))}});latestButton.onclick=()=>{selectedEventId=null;latestButton.classList.add('hidden');showEvent(eventsById.get(latestSnapshotEventId),true)};minimizeButton.onclick=()=>{const minimized=panel.classList.toggle('analytics-minimized');minimizeButton.textContent=minimized?'Show snapshot':'Minimize'};refreshEvents();const timer=setInterval(()=>{if(!drawer.isConnected)return clearInterval(timer);refreshEvents()},3000)}
